#define R2S_HASH_0_OF(CTYPE) R2S_MAP_##CTYPE##_hash_0
#define R2S_HASH_1_OF(CTYPE) R2S_MAP_##CTYPE##_hash_1
#define R2S_HASH_2_OF(CTYPE) R2S_MAP_##CTYPE##_hash_2
